# --------------------------------------------------------------------------------------------- file rules, generator, verbatim board
def test_source_rules_and_in_sync_with_generator():
    src = MEAS.read_text()
    compile(src, "measure_gemv_ws_v1.py", "exec")
    lines = src.splitlines()
    assert lines[0] == "# okc: problem=muse_bf16_proj" and "MEASUREMENT-ONLY" in lines[1] and "NEVER submit" in lines[1]
    for banned in ("subprocess", "urllib", "requests", "socket", "os.system", "import os", "environ", ".tolist(", "from reference", "import reference"):
        assert banned not in src, banned
    from tools import gen_measure_gemv_ws_v1 as gen
    assert gen.build() == src, "regenerate: .venv/bin/python tools/gen_measure_gemv_ws_v1.py"
    assert "MEASUREMENT-ONLY" not in V2.read_text() and "_gw_" not in V2.read_text()


def test_kernel_fn_and_prepare_are_v2_verbatim():
    v = V2.read_text().splitlines()
    m = MEAS.read_text().splitlines()
    start = next(i for i, line in enumerate(m) if line.startswith('"""bf16_proj candidate v2'))
    assert m[start:start + len(v) - 1] == v[1:], "director_v2 is not embedded verbatim"


def test_generate_input_recipe_equals_the_reference(mod, ref):
    if not torch.cuda.is_available():
        pytest.skip("cuda")
    for m, layer, dist in ((8, "unpooler", "normal"), (32, "router", "normal"), (1, "o", "normal")):
        a = mod._tr_generate_input(m, layer, 7, dist, "cuda")
        b = ref.generate_input(m=m, layer=layer, seed=7, dist=dist, device="cuda")
