def test_shapes_are_the_problems(mod, ref):
    for layer, m in CELLS:
        n, k = mod._gw_nk(layer, m)
        assert (n, k) == (ref.out_features(layer, m), ref.LAYERS[layer][1]), (layer, m)
    assert mod._gw_nk("unpooler", 8) == (1024, 4096) and mod._gw_nk("unpooler", 16) == (8192, 4096)


# --------------------------------------------------------------------------------------------- the instantiation table and the host code
def test_instantiation_table_agrees_with_the_host_code(mod):
    assert len(mod._GW_INST) <= 10 and len(set(mod._GW_INST)) == len(mod._GW_INST)
    host = mod._GW_HOST_SRC
    cases = re.findall(r"GW_CASE\((\d), (\d), (\d+), (\d), (\d)\)", host.split("#define GW_CASE")[1].split("#undef GW_CASE")[0].split("\n", 1)[1])
    occ = re.findall(r"GW_OCC\((\d), (\d), (\d+), (\d), (\d)\)", host.split("#define GW_OCC")[1].split("#undef GW_OCC")[0].split("\n", 1)[1])
    init = re.findall(r"gw_init_one<(\d), (\d), (\d+), (\d), (\d)>\(", host)
    want = [tuple(str(v) for v in i) for i in mod._GW_INST]
    assert [tuple(c) for c in cases] == want and [tuple(c) for c in occ] == want and [tuple(c) for c in init] == want
    assert mod._gw_inst_names() == [f"w16_gemv<{a},{b},{c},{d},{e}>" for a, b, c, d, e in mod._GW_INST]
    # one more than the table must not exist: every router instantiation has LO = 1, every BF16 one LO = 0, both tokens tiles and XS variants are present
    assert {i[0] for i in mod._GW_INST} == {1, 2} and {i[3] for i in mod._GW_INST} == {0, 1} and {i[4] for i in mod._GW_INST} == {0, 1}


def test_host_code_rules(mod):
    host, dev = mod._GW_HOST_SRC, mod._GW_DEVICE_SRC
    src = MEAS.read_text()
    assert '"-w"' in src and '"-Xptxas", "-v"' in src and "verbose=True" in src and "MEAS-GW attributes" in src
    # every CUDA call is checked, the dynamic-smem attribute is optin MINUS the static size (a C30b lesson), the launch error text names the shape
    assert "optin - (int)a.sharedSizeBytes" in host and "cudaFuncSetAttribute(fn, cudaFuncAttributeMaxDynamicSharedMemorySize, dyn)" in host
    assert re.search(r"GW_CK\(cudaFuncSetAttribute\(fn, cudaFuncAttributeMaxDynamicSharedMemorySize", host) and "cudaLaunchKernelExC" in host
    assert "gw: launch failed" in host and "cudaGetLastError();" in host
    assert 'functions=["gw_gemv", "gw_init", "gw_occupancy"]' in src
    # the study pre-flights the occupancy (a failed launch poisons a context): gw_occupancy <= 0 drops the candidate
    assert "occ < 1" in src and "gw_occupancy(inst, nw, smem)" in src
    # the kernel: weights through ld.global.nc.L1::no_allocate.v4, all U loads issued before the first use, one split-K ticket
    assert "ld.global.nc.L1::no_allocate.v4.u32" in dev and dev.count("atomicAdd") == 1
    assert dev.index("ISSUE(0)") < dev.index("mma16816(acc")
    assert "__launch_bounds__(256)" in dev and "__threadfence" in dev


def test_candidates_of_every_judged_cell_are_legal(mod):
    seen = {}
    for layer, m in CELLS:
        n, k = mod._gw_nk(layer, m)
        cands = mod._gw_candidates(layer, m, n, k)
        assert 6 <= len(cands) <= mod._GW_MAX_CAND, (layer, m, len(cands))
        names = [c[0] for c in cands]
        assert len(set(names)) == len(names)
        for name, inst, nw, split in cands:
            mt, rpw, u, xs, lo = mod._GW_INST[inst]
            assert lo == (layer == "router") and mt == (1 if m <= 16 else 2), (layer, m, name)
            wn = u // (rpw * (1 + lo))
            kc = k // split
            assert k % split == 0 and kc % (32 * wn) == 0 and kc % 64 == 0 and n % (8 * rpw * nw) == 0, (layer, m, name)
            assert mod._gw_smem(inst, m, k, split) <= 200 * 1024
            gx = n // (8 * rpw * nw)
            assert gx * split * nw * rpw * mt * 32 <= mod._GW_WS_FLOAT4 and gx <= mod._GW_DONE
        seen[(layer, m)] = len(cands)
    # the variants close to 4 CTAs / SM exist for the small cells
    assert any(split > 1 for _, _, _, split in mod._gw_candidates("o", 1, 8192, 1024))
    assert any(not mod._GW_INST[inst][3] for _, inst, _, _ in mod._gw_candidates("qkv_gate", 32, 2304, 8192))     # m = 32: x does not fit staged at split 1


def test_unique_bytes():
    mod = _load("_measure_gemv_ws_v1_b", MEAS)
    assert mod._gw_unique_bytes("qkv_gate", 1, 2304, 8192) == 2304 * 8192 * 2 + 8192 * 2 + 2304 * 2
    assert mod._gw_unique_bytes("router", 8, 256, 8192) == 256 * 8192 * 4 + 8 * 8192 * 2 + 8 * 256 * 4


# --------------------------------------------------------------------------------------------- the correctness check
@needs_cuda
@pytest.mark.parametrize("layer,m", [("router", 9), ("unpooler", 8), ("o", 33)])
def test_check_agrees_with_the_organisers(mod, ref, layer, m):
    weights = ref.generate_weights(ref.WEIGHTS_SEED, device="cuda")
    d = ref.generate_input(m=m, layer=layer, seed=2, device="cuda")
    good = ref.ref_kernel(d, weights)
    probes = ref.probe_rows(d["x"])
    assert len(probes)
    tol = 1e-4 if layer == "router" else 1e-2
    for scale in (0.0, 0.3, 0.9, 1.5, 4.0):
        out = good * (1 + scale * tol)
        want, _ = ref.check_implementation(d, out, weights)
        got, use, _, _ = mod._gw_check(out, good, d["x"], layer)
        assert want == got, (scale, use)
    bad = good.clone()
    bad[probes[0]] *= 1 + 3e-3
    want, _ = ref.check_implementation(d, bad, weights)
    got = mod._gw_check(bad, good, d["x"], layer)[0]
    assert want == got and not got
    nan = good.clone()
    nan[0, 0] = float("nan")
    assert not mod._gw_check(nan, good, d["x"], layer)[0]
    assert not mod._gw_check(good.float().to(torch.float64), good, d["x"], layer)[0]


# --------------------------------------------------------------------------------------------- the render
def _fake_results(mod, nws=6):
    res = {}
    for layer, m in CELLS:
        r = {"board": dict(kind="board", us=10.0 + m / 50, xs=[1.0, 1.0, 1.0], ok=True, use=0.1, why="", status="ok", err=1e-3),
             "cublas": dict(kind="ref", us=11.0 + m / 40, xs=[0.9, 0.9, 0.9], ok=True, use=0.1, why="", status="ok", err=1e-3)}
        for i in range(nws):
            r[f"ws.2160{i % 2}.w{i + 1}.s4"] = dict(kind="ws", us=6.0 + i, xs=[1.5, 1.6, 1.4], ok=i != 3, use=2.5 if i == 3 else 0.2, why="", status="ok" if i != 5 else "fail Error", err=2e-3)
        res[(layer, m)] = r
    return res


def test_render_size_summary_first_and_d_line(mod):
    mod._GW_NOTES[:] = ["note one", "note two " * 10]
    text = mod._gw_render(_fake_results(mod), 3.9, "NVIDIA_H200", 250.0, 41.0)
    assert len(text.encode()) <= 14000
    lines = text.splitlines()
    assert lines[0].startswith("S gemv ws v1:") and lines[1].startswith("S us =")
    first_b = next(i for i, line in enumerate(lines) if line.startswith("B "))
    assert all(line.startswith(("S ", "D ")) for line in lines[:first_b])
    d = [line for line in lines[:first_b] if line.startswith("D ")]
    assert len(d) == 1 and "on 20 of 20 cells" in d[0] and "1 WS variants outside" not in d[0]
    for line in lines[first_b:]:
        assert re.fullmatch(r"B gemv \w+ m=\d+ \| \S+ (us=\d+\.\d\d x=\d+\.\d\d( BAD\(\d+\.\d\))?|fail .*|skip.*)", line), line
    s_lines = [line for line in lines[:first_b] if re.match(r"S \w+\s+m=", line)]
    assert len(s_lines) == 20 and all("TB/s(cu/board/ws)=" in line and line.rstrip().endswith("bad=1") for line in s_lines)
    assert "S note: note one" in text
    mod._GW_NOTES[:] = []


def test_render_cuts_at_the_budget_and_handles_missing_cells(mod):
    res = _fake_results(mod, nws=60)
    text = mod._gw_render(res, 3.9, "NVIDIA_H200", 250.0, None)
    assert len(text.encode()) <= 14000
    sparse = mod._gw_render({("o", 1): res[("o", 1)]}, 3.9, "NVIDIA_H200", 10.0, 1.0)
    assert "S qkv_gate m=1: not measured" in sparse and sparse.count("\nB ") >= 3
    nobest = {("o", 1): {"board": res[("o", 1)]["board"], "cublas": res[("o", 1)]["cublas"]}}
    assert "ws=none" in mod._gw_render(nobest, 3.9, "X", 1.0, 1.0)


def test_d_line_threshold(mod):
    res = _fake_results(mod, nws=1)
    for key in res:
        res[key]["ws.21600.w1.s4"]["xs"] = [1.04, 1.04, 1.04]
    assert "on 0 of 20 cells: none" in mod._gw_render(res, 3.9, "X", 1.0, 1.0)
    res[("o", 1)]["ws.21600.w1.s4"]["xs"] = [1.06, 1.06, 1.06]
    assert "on 1 of 20 cells: o.1(1.06)" in mod._gw_render(res, 3.9, "X", 1.0, 1.0)


# --------------------------------------------------------------------------------------------- the dev card (no BF16 tensor cores: shuffle-emulated mma)
def _rand_case(mod, inst, m, K, N, seed=0):
    mt, rpw, u, xs, lo = mod._GW_INST[inst]
    g = torch.Generator(device="cuda").manual_seed(seed)
    x = torch.randn((m, K), generator=g, device="cuda").to(torch.bfloat16)
    wf = torch.randn((N, K), generator=g, device="cuda") * 0.05
    hi = wf.to(torch.bfloat16)
    low = (wf - hi.float()).to(torch.bfloat16)
    ref = x.double() @ ((hi.double() + low.double()) if lo else hi.double()).T
    return x, hi, low, ref


def _run_inst(ext, mod, inst, x, hi, low, m, N, K, nw, split, dirty=False):
    mt, rpw, u, xs, lo = mod._GW_INST[inst]
    out = torch.empty((m, N), device="cuda", dtype=torch.float32 if lo else torch.bfloat16)
    if dirty:
        out.fill_(float("nan"))
    ws = torch.full((65536, 4), float("nan") if dirty else 0.0, device="cuda")
    done = torch.zeros(1024, device="cuda", dtype=torch.int32)
    ext.gw_gemv(x, hi, low if lo else hi, out, ws, done, m, N, K, split, nw, inst, x.stride(0), out.stride(0))
    torch.cuda.synchronize()
    assert int(done.abs().sum()) == 0, "the last CTA must reset every ticket"
    return out


def _legal(mod, inst, m, K, N, nw, split):
    mt, rpw, u, xs, lo = mod._GW_INST[inst]
    wn = u // (rpw * (1 + lo))
    kc = K // split
    return (K % split == 0 and kc % (32 * wn) == 0 and kc % 64 == 0 and N % (8 * rpw * nw) == 0 and 16 * (mt - 1) < m <= 16 * mt
            and (not xs or m * (2 * kc + 64) <= 64000))


@needs_cuda
@pytest.mark.parametrize("inst", range(10))
def test_every_instantiation_matches_torch(mod, ext, inst):
    mt, rpw, u, xs, lo = mod._GW_INST[inst]
    K, N = 2048, 256
    n_run = 0
    for m in ((1, 7, 16) if mt == 1 else (17, 31, 32)):
        x, hi, low, ref = _rand_case(mod, inst, m, K, N, seed=m)
        for nw in (1, 2, 4, 8):
            for split in (1, 2, 4):
                if not _legal(mod, inst, m, K, N, nw, split):
                    continue
                out = _run_inst(ext, mod, inst, x, hi, low, m, N, K, nw, split, dirty=True)
                err = float((out.double() - ref).norm() / ref.norm())
                assert err < (3e-6 if lo else 4e-3), (inst, m, nw, split, err)          # BF16 output rounding ~ 2e-3; the router's FP32 chain ~ 1e-7
                if not lo:
                    want = ref.to(torch.bfloat16).float()
                    assert float(((out.float() - want).abs() / want.abs().clamp(min=1e-3)).max()) < 2e-2
                n_run += 1
    assert n_run >= 6, (inst, n_run)


@needs_cuda
def test_probe_rows_are_exact_and_row_tails_are_not_touched(mod, ext):
    """A one-hot token row (the probe rows of the problem) comes out exactly the rounded weight column; rows >= m of the output are never written."""
    K, N, m = 1024, 128, 5
    x = torch.zeros((m + 3, K), device="cuda", dtype=torch.bfloat16)
    cols = [3, 700, 1023, 8, 255]
    for r, c in enumerate(cols):
        x[r, c] = 64.0 * (1 if r % 2 == 0 else -1)
    g = torch.Generator(device="cuda").manual_seed(5)
    hi = (torch.randn((N, K), generator=g, device="cuda") * 0.05).to(torch.bfloat16)
    inst = 1
    out = torch.full((m + 3, N), 7.0, device="cuda", dtype=torch.bfloat16)
    ws = torch.zeros((65536, 4), device="cuda")
    done = torch.zeros(1024, device="cuda", dtype=torch.int32)
    ext.gw_gemv(x[:m], hi, hi, out, ws, done, m, N, K, 1, 2, inst, x.stride(0), out.stride(0))
    torch.cuda.synchronize()
    for r, c in enumerate(cols):
        want = (x[r, c].float() * hi[:, c].float()).to(torch.bfloat16)
        assert torch.equal(out[r], want), r
    assert bool((out[m:] == 7.0).all())


@needs_cuda
@pytest.mark.parametrize("inst,m,nw,split", [(1, 1, 2, 4), (2, 8, 4, 2), (4, 32, 1, 4), (8, 1, 2, 2), (9, 24, 4, 2), (6, 20, 4, 1)])
def test_deterministic_bit_for_bit_and_ticket_reuse(mod, ext, inst, m, nw, split):
    """Same inputs -> identical bits, also with split-K (the fixed-order last-CTA sum), on a workspace pre-filled with garbage and with the tickets reused across launches."""
    K, N = 2048, 512
    mt, rpw, u, xs, lo = mod._GW_INST[inst]
    if not _legal(mod, inst, m, K, N, nw, split):
        pytest.skip("illegal on this card")
    x, hi, low, ref = _rand_case(mod, inst, m, K, N, seed=3)
    outs = [_run_inst(ext, mod, inst, x, hi, low, m, N, K, nw, split, dirty=bool(i % 2)) for i in range(4)]
    for o in outs[1:]:
        assert torch.equal(o.view(torch.int16) if o.dtype == torch.bfloat16 else o.view(torch.int32),
                           outs[0].view(torch.int16) if o.dtype == torch.bfloat16 else outs[0].view(torch.int32))
    # one persistent workspace / ticket array for many launches (what the study does)
    ws = torch.empty((65536, 4), device="cuda")
    done = torch.zeros(1024, device="cuda", dtype=torch.int32)
    res = []
    for _ in range(5):
        out = torch.empty((m, N), device="cuda", dtype=torch.float32 if lo else torch.bfloat16)
        ext.gw_gemv(x, hi, low if lo else hi, out, ws, done, m, N, K, split, nw, inst, x.stride(0), out.stride(0))
        res.append(out)
    torch.cuda.synchronize()
    assert int(done.sum()) == 0 and all(torch.equal(r, res[0]) for r in res)
    assert torch.equal(res[0], outs[0])


@needs_cuda
def test_graph_capture_and_replay(mod, ext):
    K, N, m, inst = 2048, 256, 8, 1
    x, hi, low, ref = _rand_case(mod, inst, m, K, N, seed=9)
    ws = torch.empty((65536, 4), device="cuda")
    done = torch.zeros(1024, device="cuda", dtype=torch.int32)

    def fn(xx):
        out = torch.empty((m, N), device="cuda", dtype=torch.bfloat16)
        ext.gw_gemv(xx, hi, hi, out, ws, done, m, N, K, 2, 2, inst, xx.stride(0), out.stride(0))
        return out
    env = mod._GwEnv(torch.device("cuda"))
    g, y = env.capture(fn, x)
    for _ in range(3):
        env.replay_us(g)
    torch.cuda.synchronize()
    err = float((y.double() - ref).norm() / ref.norm())
    assert err < 4e-3 and int(done.sum()) == 0


@needs_cuda
def test_end_to_end_on_a_reduced_shape_list(mod, ref, ext, monkeypatch, capsys):
    monkeypatch.setattr(mod, "_triton_ok", lambda d: False)
    monkeypatch.setattr(mod, "_GW_MS", (1, 8))
    monkeypatch.setattr(mod, "_GW_LAYERS", ("o", "unpooler", "router"))
    monkeypatch.setattr(mod, "_GW_REPS", 2)
    monkeypatch.setitem(mod._GW_EXT, "make", lambda src: ext)
    weights = ref.generate_weights(ref.WEIGHTS_SEED, device="cuda")
    st = mod.prepare(weights)
    assert "router_hi" in st and "fix_ws" in st and "gw_ws" not in st and "gw_done" not in st          # the returned state is v2's
    out = capsys.readouterr().out
    assert "BAD(" not in out, out
    lines = out.splitlines()
    first_b = next(i for i, line in enumerate(lines) if line.startswith("B gemv"))
    assert any(line.startswith("S gemv ws v1:") for line in lines[:first_b]) and any(line.startswith("D gemv ws:") for line in lines[:first_b])
    s = [line for line in lines if re.match(r"S (o|unpooler|router)\s+m=", line)]
    assert len(s) == 6, s
    for line in s:
        assert " OK bad=0" in line and "TB/s(cu/board/ws)=" in line and " ws=" in line, line
    assert any(line.startswith("B gemv unpooler m=1 | ws.") for line in lines)
    assert any(line.startswith("B gemv router m=8 | ws.1") for line in lines)
    assert "MEAS-GW attributes" in out and len(out.encode()) < 14500
    d = ref.generate_input(m=8, layer="o", seed=1, device="cuda")
    assert ref.check_implementation(d, mod.kernel_fn(d, st), weights)[0]


@needs_cuda
def test_study_survives_a_failing_extension(mod, ref, monkeypatch, capsys):
    """No extension (build failed): the cuBLAS and board lines are still printed, with a note, and prepare() still returns the state."""
    monkeypatch.setattr(mod, "_triton_ok", lambda d: False)
    monkeypatch.setattr(mod, "_GW_MS", (1,))
    monkeypatch.setattr(mod, "_GW_LAYERS", ("o",))
    monkeypatch.setattr(mod, "_GW_REPS", 2)

    def boom(src):
        raise RuntimeError("nvcc exploded")
    monkeypatch.setitem(mod._GW_EXT, "make", boom)
    monkeypatch.setitem(mod._GW_EXT, "ext", None)
    monkeypatch.setitem(mod._GW_EXT, "err", None)
    weights = ref.generate_weights(ref.WEIGHTS_SEED, device="cuda")
    st = mod.prepare(weights)
    out = capsys.readouterr().out
    assert "router_hi" in st and "extension unavailable" in out and "ws=none" in out and "B gemv o m=1 | board" in out
    mod._GW_NOTES[:] = []


# --------------------------------------------------------------------------------------------- sm_90 audit (LAST in the file)
def _ptxas_log(nv, src, name, arch):
    from cuda.bindings import nvrtc

    # NVRTC caches a compile of identical text and then prints no ptxas -v lines: a used-nonce global makes every audit a fresh compile
    prog = nv._chk(nvrtc.nvrtcCreateProgram((src + f"\n__device__ long long gw_audit_nonce = {time.time_ns()}LL;\n").encode(), b"k.cu", 0, [], []))
    nv._chk(nvrtc.nvrtcAddNameExpression(prog, name.encode()))
    opts = [f"--gpu-architecture={arch}".encode(), b"-std=c++17", b"-default-device", b"--ptxas-options=-v"]
    res = nvrtc.nvrtcCompileProgram(prog, len(opts), opts)
    n = nv._chk(nvrtc.nvrtcGetProgramLogSize(prog))
    log = b" " * n
    nv._chk(nvrtc.nvrtcGetProgramLog(prog, log))
    assert res[0] == nvrtc.nvrtcResult.NVRTC_SUCCESS, log.decode(errors="replace")[:2000]
    return log.decode(errors="replace")


@needs_cuda
@pytest.mark.parametrize("inst", range(10))
def test_sm90_ptxas_audit(mod, nv, inst, capsys):
    """LAST: every instantiation assembles for the judge's sm_90 (ptxas): NO spills, registers within the 256-thread launch bound (a CTA of 8 warps still fits), and the PTX
    carries exactly the designed loads: two issue sites of U independent ld.global.nc.L1::no_allocate.v4 (prologue + loop), no other global v4 load of W, 2 U MT mma per round."""
    mt, rpw, u, xs, lo = mod._GW_INST[inst]
    name = mod._gw_inst_names()[inst]
    log = _ptxas_log(nv, mod._GW_DEVICE_SRC, name, "sm_90")
    mm = re.search(r"Compiling entry function '(_Z[^']*)' for 'sm_90'(.*?)Compile time", log, re.S)
    assert mm, log[-600:]
    body = mm.group(2)
    regs = int(re.search(r"Used (\d+) registers", body).group(1))
    sp = re.search(r"(\d+) bytes stack frame, (\d+) bytes spill stores, (\d+) bytes spill loads", body)
    smem = re.search(r"(\d+) bytes smem", body)
    ptx, _ = nv.compile_device(mod._GW_DEVICE_SRC, "compute_90", want="ptx", names=[name])
    ptx = ptx.decode(errors="replace")
    k = ptx[ptx.index(".entry"):]
    nxt = k.find(".visible .entry", 10)
    k = k if nxt < 0 else k[:nxt]
    stream = len(re.findall(r"ld\.global\.nc\.L1::no_allocate\.v4\.u32", k))
    xplain = len(re.findall(r"ld\.global\.nc\.v4\.u32", k))
    cg = len(re.findall(r"ld\.global\.cg\.v4\.u32", k))
    mma = len(re.findall(r"mma\.sync\.aligned\.m16n8k16\.row\.col\.f32\.bf16\.bf16\.f32", k))
    with capsys.disabled():
        print(f"\n  {name:22s} regs={regs} stack={sp.group(1)} spill_st={sp.group(2)} spill_ld={sp.group(3)} static_smem={smem.group(1) if smem else '?'} "
              f"nc.no_allocate.v4={stream} nc.v4(x)={xplain} cg.v4={cg} mma={mma}")
    assert sp.group(1) == "0" and sp.group(2) == "0" and sp.group(3) == "0", (name, sp.groups())
    assert regs <= 168, (name, regs)                  # 65536 / 256 = 256 is the hard cap of a CTA of 8 warps; <= 168 keeps 1 CTA of 8 warps + room for 2 of 4 warps
    assert stream == 2 * u, (name, stream)            # the prologue issue + the loop issue, U independent 16-byte loads each (hi + lo of the router count in U)
    assert mma == 2 * u * mt, (name, mma)
    wn = u // (rpw * (1 + lo))
    assert cg >= 1 and xplain == (1 if xs else 2 * wn * mt), (name, xplain)       # x: the one staging load (XS) or two L1 loads per window and token tile
    assert not re.search(r"ld\.global\.(?!nc|cg)[^;]*\.v4", k) and "cp.async" not in k and "st.global.v4" not in k.replace("st.global.v4.f32", "")
    assert "mma.sync.aligned.m16n8k16.row.col.f32.bf16.bf16.f32" in k and "cvt.rn.bf16x2.f32" in k or lo
    if smem:
        assert int(smem.group(1)) <= 64
